-- AD6 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD6.sql.
SELECT 'both registry tables exist with RLS enabled and forced' AS rule, (SELECT count(*) FROM pg_class c JOIN pg_namespace s ON s.oid=c.relnamespace WHERE s.nspname='desk' AND c.relname IN ('fadm_pkg','fadm_pkg_version') AND c.relrowsecurity AND c.relforcerowsecurity) = 2 AS ok
UNION ALL SELECT 'versions are append-only (update, delete, truncate triggers)', (SELECT count(*) FROM pg_trigger WHERE tgrelid='desk.fadm_pkg_version'::regclass AND tgname IN ('fadm_pkg_version_frozen','fadm_pkg_version_frozen_t')) = 2
UNION ALL SELECT 'the version guard runs before the insert', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='desk.fadm_pkg_version'::regclass AND tgname='fadm_pkg_version_00guard')
UNION ALL SELECT 'no money column exists in the registry', NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='desk' AND table_name IN ('fadm_pkg','fadm_pkg_version') AND column_name ~* '(price|amount|invoice|card|refund|currency)')
UNION ALL SELECT 'money words in features or limits are constraints', (SELECT count(*) FROM pg_constraint WHERE conrelid='desk.fadm_pkg_version'::regclass AND contype='c' AND pg_get_constraintdef(oid) ILIKE '%invoice%') >= 2
UNION ALL SELECT 'package.publish is an action with an admin policy', EXISTS (SELECT 1 FROM desk.fadm_policy WHERE name='p_package_publish' AND action='package.publish')
UNION ALL SELECT 'desk_app has no direct right on the registry tables', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid=c.relnamespace WHERE s.nspname='desk' AND c.relname IN ('fadm_pkg','fadm_pkg_version') AND (has_table_privilege('desk_app',c.oid,'SELECT') OR has_table_privilege('desk_app',c.oid,'INSERT') OR has_table_privilege('desk_app',c.oid,'UPDATE') OR has_table_privilege('desk_app',c.oid,'DELETE')))
UNION ALL SELECT 'the three registry doors are granted to desk_app', has_function_privilege('desk_app','desk.fadm_pkg_publish(uuid,text,text,date,jsonb,jsonb,int,int,text,inet)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_pkg_current(text)','EXECUTE') AND has_function_privilege('desk_app','desk.fadm_pkg_versions(text)','EXECUTE')
UNION ALL SELECT 'all SECURITY DEFINER functions pin search_path', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid=p.pronamespace WHERE s.nspname='desk' AND p.prosecdef AND (p.proconfig IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')))
UNION ALL SELECT 'ledger hash chain still verifies', desk.fadm_ledger_verify();
